using System;using System.IO;using System.Linq;using System.Text;using System.ComponentModel;using System.Runtime.Serialization;using System.Collections.Generic;
namespace CircuitoStudio {
[DataContract]public enum EarthingScheme{[EnumMember] Unknown,[EnumMember] TT,[EnumMember] TNS,[EnumMember] TNC,[EnumMember] TNCS,[EnumMember] IT}
[DataContract]public enum NeutralEarthConnection{[EnumMember] Unknown,[EnumMember] Direct,[EnumMember] Isolated,[EnumMember] Impedance}
[DataContract]public enum LiveConnection{[EnumMember] Unknown,[EnumMember] LineNeutral,[EnumMember] LineLine,[EnumMember] ThreePhase,[EnumMember] ThreePhaseNeutral}
[DataContract]public enum EquipmentInsulation{[EnumMember] Unknown,[EnumMember] ClassI,[EnumMember] ClassII}
[DataContract,TypeConverter(typeof(ExpandableObjectConverter))]public sealed class GroundingSource {
[DataMember,Browsable(false)]public string Engine{get;set;}[DataMember,DisplayName("Esquema TT/TN/IT")]public EarthingScheme Scheme{get;set;}[DataMember,DisplayName("Ligação do neutro à terra")]public NeutralEarthConnection NeutralConnection{get;set;}[DataMember,DisplayName("Neutro distribuído")]public bool? NeutralDistributed{get;set;}[DataMember,DisplayName("Ra da instalação (Ω), vazio=desconhecido")]public double? InstallationRaOhm{get;set;}[DataMember,DisplayName("Rb da fonte (Ω), vazio=desconhecido")]public double? SourceRbOhm{get;set;}[DataMember,DisplayName("R de aterramento IT (Ω)")]public double? GroundingROhm{get;set;}[DataMember,DisplayName("X de aterramento IT (Ω)")]public double? GroundingXOhm{get;set;}[DataMember,DisplayName("Referência dos dados")]public string Reference{get;set;}[DataMember,DisplayName("Versão dos dados")]public string DataVersion{get;set;}[DataMember,DisplayName("Condições / grupo de massas")]public string Conditions{get;set;}
public GroundingSource(){Engine=Grounding.EngineId;Reference=DataVersion=Conditions="";}public GroundingSource Copy(){return (GroundingSource)MemberwiseClone();}
public void Validate(){if(Engine!=Grounding.EngineId||!Enum.IsDefined(typeof(EarthingScheme),Scheme)||!Enum.IsDefined(typeof(NeutralEarthConnection),NeutralConnection))throw new InvalidDataException("Esquema/revisão de aterramento desconhecidos.");foreach(var x in new[]{InstallationRaOhm,SourceRbOhm,GroundingROhm,GroundingXOhm})if(x.HasValue)Project.Range(x.Value,0,1e12,"impedância/resistência de terra");foreach(var s in new[]{Reference,DataVersion,Conditions})if(s==null||s.Length>2000||s.IndexOf('\0')>=0)throw new InvalidDataException("Referência de aterramento inválida.");if(Scheme!=EarthingScheme.Unknown&&Scheme!=EarthingScheme.IT&&(NeutralConnection==NeutralEarthConnection.Isolated||NeutralConnection==NeutralEarthConnection.Impedance))throw new InvalidDataException("TT/TN exigem fonte diretamente aterrada.");if(Scheme==EarthingScheme.IT&&NeutralConnection==NeutralEarthConnection.Direct)throw new InvalidDataException("IT não permite neutro diretamente aterrado.");if(NeutralConnection!=NeutralEarthConnection.Impedance&&(GroundingROhm.HasValue||GroundingXOhm.HasValue))throw new InvalidDataException("R/X de aterramento se aplicam somente à ligação por impedância.");if(NeutralConnection==NeutralEarthConnection.Impedance&&GroundingROhm.HasValue&&GroundingXOhm.HasValue&&GroundingROhm.Value==0&&GroundingXOhm.Value==0)throw new InvalidDataException("Impedância nula equivale a ligação direta, incompatível com IT.");}
}
[DataContract,TypeConverter(typeof(ExpandableObjectConverter))]public sealed class CircuitConductors {
[DataMember,DisplayName("Ligação dos condutores")]public LiveConnection Connection{get;set;}[DataMember,DisplayName("Possui N separado")]public bool? HasNeutral{get;set;}[DataMember,DisplayName("Possui PE separado")]public bool? HasPE{get;set;}[DataMember,DisplayName("Possui PEN combinado")]public bool? HasPEN{get;set;}[DataMember,DisplayName("Classe de isolação")]public EquipmentInsulation Insulation{get;set;}[DataMember,DisplayName("Referência dos dados")]public string Reference{get;set;}
public CircuitConductors(){Reference="";}public CircuitConductors Copy(){return (CircuitConductors)MemberwiseClone();}
public void Validate(){if(!Enum.IsDefined(typeof(LiveConnection),Connection)||!Enum.IsDefined(typeof(EquipmentInsulation),Insulation)||Reference==null||Reference.Length>2000||Reference.IndexOf('\0')>=0)throw new InvalidDataException("Condutores/referência inválidos.");if(HasPEN==true&&(HasNeutral==true||HasPE==true))throw new InvalidDataException("Trecho PEN não pode declarar simultaneamente N ou PE separados.");if(Insulation==EquipmentInsulation.ClassI&&HasPE==false&&HasPEN==false)throw new InvalidDataException("Equipamento classe I precisa de PE ou PEN.");}
}
public sealed partial class Project{[DataMember(Order=111),Browsable(false)]public GroundingSource GroundingSource{get;set;}}
public sealed partial class Board{[DataMember(Order=111),Category("Aterramento"),DisplayName("Separação PEN neste quadro")]public bool SeparatesPEN{get;set;}}
public sealed partial class Circuit{[DataMember(Order=111),Browsable(false)]public CircuitConductors Conductors{get;set;}}
public static class Grounding {
public const string EngineId="cs-aterramento-condutores-v1";
public static string Name(EarthingScheme scheme){switch(scheme){case EarthingScheme.TNS:return "TN-S";case EarthingScheme.TNC:return "TN-C";case EarthingScheme.TNCS:return "TN-C-S";case EarthingScheme.Unknown:return "A definir";default:return scheme.ToString();}}
public static bool Combined(Project p,Board b){if(p.GroundingSource==null)return false;if(p.GroundingSource.Scheme==EarthingScheme.TNC)return true;if(p.GroundingSource.Scheme!=EarthingScheme.TNCS)return false;var current=b;var seen=new HashSet<string>();while(current!=null&&seen.Add(current.Id)){if(current.SeparatesPEN)return false;var incoming=p.Boards.FirstOrDefault(x=>x.Circuits.Any(c=>c.ChildBoardId==current.Id));current=incoming;}return true;}
public static string EffectiveSystem(Project p,Circuit c){if(p.GroundingSource==null)return p.Earthing;var board=p.Boards.FirstOrDefault(b=>b.Circuits.Contains(c));if(p.GroundingSource.Scheme==EarthingScheme.TNCS&&board!=null)return Combined(p,board)?"TN-C":"TN-S";return Name(p.GroundingSource.Scheme);}
public static double? Ra(Project p,Circuit c){return p.GroundingSource==null?(c.Protection.EarthResistanceOhm>0?(double?)c.Protection.EarthResistanceOhm:null):p.GroundingSource.InstallationRaOhm;}
public static void Validate(Project p){var source=p.GroundingSource;if(source==null){if(p.Boards.Any(b=>b.SeparatesPEN||b.Circuits.Any(c=>c.Conductors!=null)))throw new InvalidDataException("Declare fonte/esquema tipado antes de condutores/separação PEN.");return;}source.Validate();if(p.Earthing!=Name(source.Scheme))throw new InvalidDataException("Esquema legado e esquema tipado devem concordar; edite pelo painel Aterramento.");foreach(var b in p.Boards){if(b.SeparatesPEN){if(source.Scheme!=EarthingScheme.TNCS)throw new InvalidDataException("Separação PEN só se aplica ao TN-C-S.");var parent=p.Boards.FirstOrDefault(x=>x.Circuits.Any(c=>c.ChildBoardId==b.Id));if(parent!=null&&!Combined(p,parent))throw new InvalidDataException("PEN já separado a montante; não é permitido reuni-lo e separar novamente.");}bool combined=Combined(p,b);foreach(var c in b.Circuits){var w=c.Conductors;if(combined&&(c.Protection.RcdMilliA>0||c.ResidualSelection!=null))throw new InvalidDataException("Diferencial não pode atuar em trecho TN-C/PEN combinado.");if(w==null)continue;w.Validate();if(w.HasPEN==true&&!combined)throw new InvalidDataException("PEN proibido em TT/IT/TN-S ou após separação do PEN.");if(combined&&(w.HasPE==true||w.HasNeutral==true))throw new InvalidDataException("Trecho combinado exige PEN, sem N/PE separados. Declare separação no quadro TN-C-S.");if(source.NeutralDistributed==false&&(w.HasNeutral==true||w.HasPEN==true||w.Connection==LiveConnection.LineNeutral||w.Connection==LiveConnection.ThreePhaseNeutral))throw new InvalidDataException("Fonte sem neutro distribuído não fornece N/PEN.");if(w.Connection==LiveConnection.LineNeutral||w.Connection==LiveConnection.ThreePhaseNeutral){if(w.HasNeutral==false&&w.HasPEN==false)throw new InvalidDataException("Ligação com neutro exige N ou PEN.");}if(w.HasNeutral==true||w.HasPEN==true||w.Connection==LiveConnection.LineNeutral||w.Connection==LiveConnection.ThreePhaseNeutral){var ancestor=b;while(true){var parent=p.Boards.FirstOrDefault(x=>x.Circuits.Any(f=>f.ChildBoardId==ancestor.Id));if(parent==null)break;var incoming=parent.Circuits.First(f=>f.ChildBoardId==ancestor.Id);if(incoming.Conductors!=null&&incoming.Conductors.HasNeutral==false&&incoming.Conductors.HasPEN==false)throw new InvalidDataException("Neutro exigido a jusante, mas alimentador a montante não possui N/PEN.");ancestor=parent;}}if(w.Connection!=LiveConnection.Unknown){bool three=w.Connection==LiveConnection.ThreePhase||w.Connection==LiveConnection.ThreePhaseNeutral;double expected=w.Connection==LiveConnection.LineNeutral?b.Voltage/Math.Sqrt(3):b.Voltage;if((c.Phases==PhaseMode.Trifasico)!=three||Math.Abs(c.Voltage-expected)>.01*expected)throw new InvalidDataException("Ligação dos condutores não corresponde às fases/tensão do circuito e quadro.");}if(c.ChildBoardId!=""&&w.Connection!=LiveConnection.Unknown&&w.Connection!=LiveConnection.ThreePhase&&w.Connection!=LiveConnection.ThreePhaseNeutral)throw new InvalidDataException("Alimentador de quadro exige ligação trifásica.");}}}
public static bool Complete(Project p,Circuit c){if(p.GroundingSource==null)return false;var s=p.GroundingSource;var w=c.Conductors;bool pending=s.Scheme==EarthingScheme.Unknown||s.NeutralConnection==NeutralEarthConnection.Unknown||!s.NeutralDistributed.HasValue||String.IsNullOrWhiteSpace(s.Reference)||String.IsNullOrWhiteSpace(s.DataVersion)||String.IsNullOrWhiteSpace(s.Conditions)||w==null;if(w!=null)pending|=w.Connection==LiveConnection.Unknown||!w.HasNeutral.HasValue||!w.HasPE.HasValue||!w.HasPEN.HasValue||w.Insulation==EquipmentInsulation.Unknown||String.IsNullOrWhiteSpace(w.Reference);if(s.Scheme==EarthingScheme.TT||s.Scheme==EarthingScheme.IT)pending|=!s.InstallationRaOhm.HasValue;if(s.NeutralConnection==NeutralEarthConnection.Impedance)pending|=!s.GroundingROhm.HasValue||!s.GroundingXOhm.HasValue;return !pending;}
public static string Describe(Project p,Circuit c){if(p.GroundingSource==null)return "Aterramento tipado não informado; dados legados preservados.";var s=p.GroundingSource;var b=p.Boards.First(x=>x.Circuits.Contains(c));var w=c.Conductors;bool pending=!Complete(p,c);return (pending?"Dados incompletos. ":"Topologia declarada consistente. ")+EngineId+"; esquema "+Name(s.Scheme)+"; trecho "+EffectiveSystem(p,c)+"; neutro da fonte "+s.NeutralConnection+"; N distribuído="+s.NeutralDistributed+"; Ra="+(s.InstallationRaOhm.HasValue?s.InstallationRaOhm+" Ω":"desconhecida")+"; Rb="+(s.SourceRbOhm.HasValue?s.SourceRbOhm+" Ω":"desconhecida")+"; Zg R/X="+s.GroundingROhm+" / "+s.GroundingXOhm+" Ω; fonte "+s.Reference+"; versão "+s.DataVersion+"; condições "+s.Conditions+"; separação neste quadro="+b.SeparatesPEN+". "+(w==null?"Condutores não definidos.":"Ligação="+w.Connection+"; N="+w.HasNeutral+"; PE="+w.HasPE+"; PEN="+w.HasPEN+"; classe="+w.Insulation+"; referência="+w.Reference+".")+" Um grupo comum de massas/PE por projeto; não modela grupos de terra independentes, continuidade medida, seções mínimas, IMD, laço de falta ou tempo de desligamento nesta etapa. Ra tipada prevalece na avaliação TT, sem apagar o valor legado. Desconhecido é distinto de zero ideal declarado.";}
public static void ApplySource(Project p,GroundingSource source){if(source==null)throw new InvalidDataException("Fonte ausente.");var old=p.GroundingSource;string name=p.Earthing;p.GroundingSource=source.Copy();p.Earthing=Name(source.Scheme);try{p.Validate();}catch{p.GroundingSource=old;p.Earthing=name;throw;}}
public static void ApplyConductors(Project p,Circuit c,CircuitConductors w){if(!p.Boards.Any(b=>b.Circuits.Contains(c)))throw new InvalidDataException("Circuito fora do projeto.");var old=c.Conductors;c.Conductors=w==null?null:w.Copy();try{p.Validate();}catch{c.Conductors=old;throw;}}
}
}
